class Solution {
public:
    int minIncrementForUnique(vector<int>& nums) {
        int n = nums.size();
        int maxVal = 0;
        for (int x : nums) maxVal = max(maxVal, x);
        int size = maxVal + n + 1;
        vector<int> count(size, 0);
        for (int x : nums) count[x]++;
        long long moves = 0;
        for (int v = 0; v < size - 1; v++) {
            if (count[v] > 1) {
                int extra = count[v] - 1;
                moves += extra;
                count[v + 1] += extra;
            }
        }
        return (int)moves;
    }
};
